using System;
using System.Collections.Generic;

namespace ModelTest;

/// <summary>
/// 默认参数提供器。
/// 负责把“菜单业务语义”和“真实接口名”映射到一组可直接执行的默认参数。
/// </summary>
public interface IWinSocketServiceDefaultParameterProvider
{
    string GetDefaultParameters(string? selectionKey, string? serviceName, bool usePrivateKey);
}

public sealed class WinSocketServiceDefaultParameterProvider : IWinSocketServiceDefaultParameterProvider
{
    // 不同接口的默认参数生成规则并不完全相同，因此使用委托统一包装。
    private delegate string ParameterResolver(bool usePrivateKey);

    private const string TerminalTrmKeyUpdateParameters =
        "00000000000000000000000000000000,7501000000047B1C,,0000100000000001,00";

    private const string TerminalSetDataParameters =
        "3,7501000000047B1C,,060105400002001C07E7010A121A2800";

    private const string VerifyTerminalDataPrivateParameters =
        "1,3,750100000063E36,,A8EF3E51884C90DC21A66E01BAC3348F,C638B09C";

    private const string InitSessionPrivateParameters =
        "1,7501000000296233,00000095,";

    private const string VerifySessionPrivateParameters =
        "1,7501000000296233,3E6658F5B6D7B9F73E6658F5B6D7B9F7,619B41068258A44CD10286F06C3474E1F565C5459392BE9792C6307A1A2A90CA269DFBFB5473ABBBFF155BEA5A2E1AAE,AF8ABF1EF095FAD80D7EC4DB408A19CD94FF58583E55ADE535D1A95D82F70A9D428B85B7D7AF33161B2F467F737ACCBD043DF679E9900F37CE6A1456C8028ABF,";

    private const string InitSessionRhPrivateParameters =
        "1,810100000003D996,000002DA,";

    private const string VerifySessionRhPrivateParameters =
        "1,8101000000000028,8D4E6B9522CF9FD5193D07E74FE0EF44,67AF497C1B51241D10ABA1C604CC6775B3C53E7288711C64A856ABC8FB9AA0BB52AD7BBA2CC4EC430DC4EEFE31A4433E,08804B6CFE8E1DF28975EA2C2B636591DC3B498AAB391346CA86E0E03EC679F3B6AB35ED7B6F5B6A1EF53967608D4A0534E303425BF2059AA5A1877A2F6B65CA,";

    private const string SessionDataRhParameters =
        "8101000000004832,31,0001,,3,07010E430003000000";

    private const string TerminalTrmKeyUpdateRhPrivateParameters =
        "1,8101000000004906,,0000012539268422,00";

    private const string Meter698IdentityAuthenticationParameters =
        "1,51010000034D7471,,10,0000271000000001000000360590";

    private const string Meter698RemoteRechargeParameters =
        "1,51010000034D7471,,10,0000271000000001000000360590";

    private const string Meter698TrmKeyUpdateParameters =
        "1,7001000000017B23,,0000000000000001,00";

    private const string Meter698TrmKeyRecoverParameters =
        "0,7001000000017B23,,0000000000000001,00";

    private const string Meter645IdentityAuthenticationPublicParameters = "0,0000000000000001";
    private const string Meter645IdentityAuthenticationPrivateParameters = "1,0000000000000001";

    private const string Meter645RemoteControlPublicParameters =
        "0,D3C60A0D,0000000000000001,0101000011CC0260,1A00260811132844";

    private const string Meter645RemoteControlPrivateParameters =
        "1,D3C60A0D,0000000000000001,0101000011CC0260,1A00260811132844";

    private const string Meter645TrmKeyUpdateParameters =
        "20,01,00010203,D2D61AC3,0000000000000001,0101000014BB3A99,18111909350101000042500000000101000014BB3A9901010007B0658871E31DA70511F1DE0D1B26F819BB61D3D0FB18DD628DE7392491FB1DB8AA4F932E42F718562CCF8965BD94F161BAEE6650178293D41D6E96726497BDA2";

    private const string Meter645TrmKeyRecoverParameters =
        "20,00,00010203,D2D61AC3,0000000000000001,0101000014BB3A99,18111909350101000042500000000101000014BB3A9901010007B0658871E31DA70511F1DE0D1B26F819BB61D3D0FB18DD628DE7392491FB1DB8AA4F932E42F718562CCF8965BD94F161BAEE6650178293D41D6E96726497BDA2";

    // 菜单项名和接口名都允许作为 key。
    // 这样既支持业务菜单回填，也支持用户直接从接口下拉框选中时的兜底回填。
    private static readonly Dictionary<string, ParameterResolver> ParameterResolvers = new(StringComparer.Ordinal)
    {
        ["（698）终端对称密钥更新"] = _ => TerminalTrmKeyUpdateParameters,
        ["Obj_Terminal_Formal_GetTrmKeyData"] = _ => TerminalTrmKeyUpdateParameters,

        ["（698）终端任务数据"] = _ => TerminalSetDataParameters,
        ["（698）终端任务数据-密钥更新"] = _ => TerminalSetDataParameters,
        ["Obj_Terminal_Formal_GetTerminalSetData"] = _ => TerminalSetDataParameters,

        ["（698）验证终端返回数据"] = usePrivateKey => ToggleKeyPrefix(VerifyTerminalDataPrivateParameters, usePrivateKey),
        ["Obj_Terminal_Formal_VerifyTerminalData"] = usePrivateKey => ToggleKeyPrefix(VerifyTerminalDataPrivateParameters, usePrivateKey),

        ["（698）主站会话协商数据"] = usePrivateKey => ToggleKeyPrefix(InitSessionPrivateParameters, usePrivateKey),
        ["Obj_Terminal_Formal_InitSession"] = usePrivateKey => ToggleKeyPrefix(InitSessionPrivateParameters, usePrivateKey),

        ["（698）主站会话协商验证"] = usePrivateKey => ToggleKeyPrefix(VerifySessionPrivateParameters, usePrivateKey),
        ["Obj_Terminal_Formal_VerifySession"] = usePrivateKey => ToggleKeyPrefix(VerifySessionPrivateParameters, usePrivateKey),

        ["（698）主站会话协商数据-IFT"] = usePrivateKey => ToggleKeyPrefix(InitSessionRhPrivateParameters, usePrivateKey),
        ["Obj_Terminal_Formal_InitSession_RH"] = usePrivateKey => ToggleKeyPrefix(InitSessionRhPrivateParameters, usePrivateKey),

        ["（698）主站会话协商验证-IFT"] = usePrivateKey => ToggleKeyPrefix(VerifySessionRhPrivateParameters, usePrivateKey),
        ["Obj_Terminal_Formal_VerifySession_RH"] = usePrivateKey => ToggleKeyPrefix(VerifySessionRhPrivateParameters, usePrivateKey),

        ["（698）安全传输加密-IFT"] = _ => SessionDataRhParameters,
        ["Obj_Terminal_Formal_GetSessionData_RH"] = _ => SessionDataRhParameters,

        ["（698）终端对称密钥更新-IFT"] = _ => TerminalTrmKeyUpdateRhPrivateParameters,
        ["（698）终端对称密钥恢复-IFT"] = _ => ToggleKeyPrefix(TerminalTrmKeyUpdateRhPrivateParameters, usePrivateKey: false),
        ["Obj_Terminal_Formal_GetTrmKeyData_RH"] = usePrivateKey => ToggleKeyPrefix(TerminalTrmKeyUpdateRhPrivateParameters, usePrivateKey),

        ["（698）身份认证函数"] = _ => Meter698IdentityAuthenticationParameters,
        ["Obj_Meter_Formal_GetSessionData"] = _ => Meter698IdentityAuthenticationParameters,

        ["（698）远程充值函数"] = _ => Meter698RemoteRechargeParameters,
        ["Obj_Meter_Formal_GetPurseData"] = _ => Meter698RemoteRechargeParameters,

        ["（698）电表对称密钥更新"] = _ => Meter698TrmKeyUpdateParameters,

        ["（698）电表对称密钥恢复"] = _ => Meter698TrmKeyRecoverParameters,
        ["Obj_Meter_Formal_GetTrmKeyData"] = _ => Meter698TrmKeyUpdateParameters,

        ["（645）身份认证函数"] = usePrivateKey => usePrivateKey
            ? Meter645IdentityAuthenticationPrivateParameters
            : Meter645IdentityAuthenticationPublicParameters,
        ["Meter_Formal_IdentityAuthentication"] = usePrivateKey => usePrivateKey
            ? Meter645IdentityAuthenticationPrivateParameters
            : Meter645IdentityAuthenticationPublicParameters,

        ["（645）远程控制"] = usePrivateKey => usePrivateKey
            ? Meter645RemoteControlPrivateParameters
            : Meter645RemoteControlPublicParameters,
        ["Meter_Formal_UserControl"] = usePrivateKey => usePrivateKey
            ? Meter645RemoteControlPrivateParameters
            : Meter645RemoteControlPublicParameters,

        ["（645）电表对称密钥更新"] = _ => Meter645TrmKeyUpdateParameters,

        ["（645）电表对称密钥恢复"] = _ => Meter645TrmKeyRecoverParameters,
        ["Meter_Formal_KeyUpdateV2"] = _ => Meter645TrmKeyUpdateParameters,
    };

    /// <summary>
    /// 先按菜单项 key 回填，命中失败再按真实接口名回填。
    /// </summary>
    public string GetDefaultParameters(string? selectionKey, string? serviceName, bool usePrivateKey)
    {
        if (TryResolve(selectionKey, usePrivateKey, out string parameters))
        {
            return parameters;
        }

        if (!string.Equals(selectionKey, serviceName, StringComparison.Ordinal)
            && TryResolve(serviceName, usePrivateKey, out parameters))
        {
            return parameters;
        }

        return string.Empty;
    }

    /// <summary>
    /// 尝试解析默认参数。
    /// </summary>
    private static bool TryResolve(string? key, bool usePrivateKey, out string parameters)
    {
        parameters = string.Empty;
        if (string.IsNullOrWhiteSpace(key))
        {
            return false;
        }

        if (!ParameterResolvers.TryGetValue(key, out ParameterResolver? resolver))
        {
            return false;
        }

        parameters = resolver(usePrivateKey);
        return !string.IsNullOrWhiteSpace(parameters);
    }

    /// <summary>
    /// 公钥/私钥切换本质上只是首参 0/1 变化的接口，统一用这个方法改写前缀。
    /// </summary>
    private static string ToggleKeyPrefix(string privateKeyParameters, bool usePrivateKey)
    {
        if (string.IsNullOrWhiteSpace(privateKeyParameters))
        {
            return string.Empty;
        }

        char desiredPrefix = usePrivateKey ? '1' : '0';
        return privateKeyParameters[0] == desiredPrefix
            ? privateKeyParameters
            : $"{desiredPrefix}{privateKeyParameters[1..]}";
    }
}
